definition.script:
def wealthAllDesc() {
  def parts = []
  for (mod in ['gateway', 'auth', 'system-server', 'admin-server', 'ecommerce-server', 'freedom-web', 'ecommerce-web']) {
    def mf = "${env.WORKSPACE}/.wealth-meta-${mod}"
    if (!fileExists(mf)) { continue }
    def m = [:]
    for (l in readFile(mf).trim().split('\n')) {
      def i = l.indexOf('=')
      if (i > 0) { m[l.substring(0, i)] = l.substring(i + 1).trim() }
    }
    parts << "${mod}: 分支 ${m.BRANCH} | SHA ${m.SHA} | tag ${m.IMAGE_TAG}"
  }
  def head = "wealth-all MODE=${params.MODE} OVERLAY=${params.OVERLAY} IMAGE_TAG=${params.IMAGE_TAG}"
  currentBuild.description = parts ? (head + ' | ' + parts.join(' ; ')) : head
}

pipeline {
  agent any
  options { timestamps(); disableConcurrentBuilds(); buildDiscarder(logRotator(numToKeepStr: '10')) }
  stages {
    stage('All modules') {
      steps {
        sh '''
          set -euo pipefail
          export MODE="${MODE}"
          export OVERLAY="${OVERLAY}"
          export SOURCE="${SOURCE}"
          export IMAGE_TAG="${IMAGE_TAG}"
          export REGISTRY="${REGISTRY:-}"
          export BRANCH="${BRANCH}"
          export GIT_SHA="${GIT_SHA:-}"
          export SKIP_MVN="$([ "${SKIP_MVN}" = "true" ] && echo 1 || echo 0)"
          export WORKSPACE_ROOT="${WORKSPACE}/repos"
          export JAVA_HOME=/opt/java/jdk-25
          export PATH="$JAVA_HOME/bin:/opt/maven/bin:/usr/local/bin:$PATH"
          bash /jenkins-backup/scripts/pipeline-wealth-all.sh
        '''
      }
    }
  }
  post {
    always {
      script { wealthAllDesc() }
    }
  }
}
